=== FILE: rr_arbiter.v ===
// rr_arbiter.v
// Round-robin arbiter for N requesters (default N = 4).
// Implements microarchitecture.md: one priority pointer `ptr`, a wrapping
// priority search from `ptr` that wraps at N-1 (not at a power of two),
// combinational same-cycle grant, and a pointer that moves one past the
// winner on every rising edge with a grant.
`default_nettype none

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);
    // Pointer width: $clog2(N) bits (N >= 2).
    localparam integer  PW     = (N > 1) ? $clog2(N) : 1;
    localparam [31:0]   LAST_I = N - 1;
    localparam [31:0]   ONE_I  = 1;
    localparam [PW-1:0] LAST   = LAST_I[PW-1:0];
    localparam [PW-1:0] ONE_P  = ONE_I[PW-1:0];
    localparam [PW-1:0] ZERO_P = {PW{1'b0}};
    localparam [N-1:0]  ONE_N  = {{(N-1){1'b0}}, 1'b1};

    // State: index of the requester with the highest priority this cycle.
    reg [PW-1:0] ptr;

    // Combinational search results.
    reg [PW-1:0] winner;
    reg [PW-1:0] cand;
    reg          found;
    integer      k;

    // Wrapping priority search from ptr. Every output is assigned a
    // default first, so synthesis infers pure logic and no latch.
    always @(*) begin
        found  = 1'b0;
        winner = ptr;
        cand   = ptr;
        for (k = 0; k < N; k = k + 1) begin
            if (!found && req[cand]) begin
                found  = 1'b1;
                winner = cand;
            end
            cand = (cand == LAST) ? ZERO_P : cand + ONE_P;
        end
        grant = found ? (ONE_N << winner) : {N{1'b0}};
    end

    // Pointer update: synchronous active-low reset to 0; on a grant move to
    // one past the winner, wrapping at N-1; otherwise hold.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= ZERO_P;
        end else if (found) begin
            ptr <= (winner == LAST) ? ZERO_P : winner + ONE_P;
        end
    end

`ifdef FORMAL
    // Design-intent assertions (not proven in this deliverable).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
        if (f_past_valid) begin
            // Pointer in range.
            assert (ptr <= LAST);
            // Grant is one-hot or zero.
            assert ((grant & (grant - ONE_N)) == {N{1'b0}});
            // Grant only to a requester.
            assert ((grant & ~req) == {N{1'b0}});
            // Work conserving.
            if (req != {N{1'b0}}) assert (grant != {N{1'b0}});
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n))
                assert (ptr == ZERO_P);
            else if ($past(found))
                assert (ptr == (($past(winner) == LAST) ? ZERO_P : $past(winner) + ONE_P));
            else
                assert (ptr == $past(ptr));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
