// rr_arbiter_tb.v
// Self-checking testbench for rr_arbiter. Two harnesses run side by side,
// N = 4 and N = 5 (not a power of two), each against a reference pointer
// model with per-requester wait counters and coverage counters.
`default_nettype none

module rr_arbiter_tb_harness #(
    parameter integer N    = 4,
    parameter integer SEED = 1
) (
    input wire clk
);
    localparam integer PW     = (N > 1) ? $clog2(N) : 1;
    localparam [N-1:0] ZERO_N = {N{1'b0}};
    localparam [N-1:0] ALL_N  = {N{1'b1}};
    localparam [N-1:0] ONE_N  = {{(N-1){1'b0}}, 1'b1};

    reg          rst_n;
    reg  [N-1:0] req;
    wire [N-1:0] grant;

    rr_arbiter #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    // Check accounting
    integer passed;
    integer failed;
    integer cyc;

    // Reference model
    integer     model_ptr;
    integer     exp_w;
    integer     gcnt;
    integer     tidx;
    reg [N-1:0] exp_grant;
    reg         armed;
    reg         done;

    // Fairness
    integer waitc [0:N-1];
    integer max_wait;

    // Coverage
    integer cov_idle;
    integer cov_all;
    integer cov_rot;
    integer cov_held;
    integer cov_maxwait;
    integer cov_rst;
    integer cov_alone [0:N-1];

    // Stimulus state
    reg         rot_mode;
    reg         held_mode;
    integer     rot_cnt;
    integer     held_id;
    integer     seed;
    integer     rnd;
    integer     rnd2;
    integer     si;
    integer     sk;
    integer     j;
    integer     h;
    integer     t;
    reg [N-1:0] v;
    reg         r;

    function bit_at;
        input [N-1:0] vec;
        input integer pos;
        reg   [N-1:0] sh;
        begin
            sh     = vec >> pos;
            bit_at = sh[0];
        end
    endfunction

    task chk;
        input         ok;
        input integer id;
        begin
            if (ok) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                case (id)
                    1: $error("rr_arbiter N=%0d cycle %0d: grant %b differs from reference %b (req %b, model ptr %0d)", N, cyc, grant, exp_grant, req, model_ptr);
                    2: $error("rr_arbiter N=%0d cycle %0d: grant %b is not one-hot or zero", N, cyc, grant);
                    3: $error("rr_arbiter N=%0d cycle %0d: grant %b to a non-requester (req %b)", N, cyc, grant, req);
                    4: $error("rr_arbiter N=%0d cycle %0d: not work conserving (req %b, grant %b)", N, cyc, req, grant);
                    5: $error("rr_arbiter N=%0d cycle %0d: held request waited %0d cycles or more (req %b, grant %b)", N, cyc, N, req, grant);
                    6: $error("rr_arbiter N=%0d cycle %0d: strict rotation broken, step %0d grant %b", N, cyc, rot_cnt, grant);
                    7: $error("rr_arbiter N=%0d cycle %0d: pointer %0d differs from reference %0d", N, cyc, dut.ptr, model_ptr);
                    10: $error("rr_arbiter N=%0d: coverage miss: no-request cycles", N);
                    11: $error("rr_arbiter N=%0d: coverage miss: a requester was never granted alone", N);
                    12: $error("rr_arbiter N=%0d: coverage miss: everyone-requesting rotation", N);
                    13: $error("rr_arbiter N=%0d: coverage miss: held request among changing others", N);
                    14: $error("rr_arbiter N=%0d: coverage miss: longest fair wait N-1 (max seen %0d)", N, max_wait);
                    15: $error("rr_arbiter N=%0d: coverage miss: reset during traffic", N);
                    default: $error("rr_arbiter N=%0d cycle %0d: check %0d failed", N, cyc, id);
                endcase
            end
        end
    endtask

    // One clock cycle: drive at negedge, check before the rising edge,
    // update the reference model after it.
    task step;
        input         r_in;
        input [N-1:0] q_in;
        begin
            @(negedge clk);
            rst_n = r_in;
            req   = q_in;
            #1;
            cyc = cyc + 1;
            if (armed) begin
                // Reference: first requester at or after the pointer.
                exp_w = -1;
                for (sk = 0; sk < N; sk = sk + 1) begin
                    tidx = model_ptr + sk;
                    if (tidx >= N) tidx = tidx - N;
                    if ((exp_w < 0) && bit_at(req, tidx)) exp_w = tidx;
                end
                exp_grant = (exp_w >= 0) ? (ONE_N << exp_w) : ZERO_N;
                chk(grant === exp_grant, 1);

                // Independent properties.
                gcnt = 0;
                for (sk = 0; sk < N; sk = sk + 1) begin
                    if (bit_at(grant, sk)) gcnt = gcnt + 1;
                end
                chk(gcnt <= 1, 2);
                chk((grant & ~req) === ZERO_N, 3);
                chk((req === ZERO_N) || (grant !== ZERO_N), 4);

                // Strict rotation with everyone requesting after reset.
                if (rot_mode && rst_n) begin
                    chk(grant === (ONE_N << (rot_cnt % N)), 6);
                    rot_cnt = rot_cnt + 1;
                    cov_rot = cov_rot + 1;
                end

                // Fairness: no held request waits N cycles.
                for (si = 0; si < N; si = si + 1) begin
                    if (!rst_n || !bit_at(req, si)) begin
                        waitc[si] = 0;
                    end else if (bit_at(grant, si)) begin
                        if (waitc[si] == N - 1) cov_maxwait = cov_maxwait + 1;
                        if (waitc[si] > max_wait) max_wait = waitc[si];
                        waitc[si] = 0;
                    end else begin
                        waitc[si] = waitc[si] + 1;
                        chk(waitc[si] <= N - 1, 5);
                    end
                    if (rst_n && (req === (ONE_N << si)) && (grant === req))
                        cov_alone[si] = cov_alone[si] + 1;
                end

                // Coverage.
                if (rst_n && (req === ZERO_N)) cov_idle = cov_idle + 1;
                if (rst_n && (req === ALL_N))  cov_all  = cov_all + 1;
                if (rst_n && held_mode && bit_at(req, held_id)) cov_held = cov_held + 1;
                if (!rst_n && (req !== ZERO_N)) cov_rst = cov_rst + 1;
            end

            @(posedge clk);
            #1;
            if (!rst_n)
                model_ptr = 0;
            else if (armed && (exp_w >= 0))
                model_ptr = (exp_w == N - 1) ? 0 : exp_w + 1;
            if (armed) chk(dut.ptr === model_ptr[PW-1:0], 7);
            if (!rst_n) armed = 1'b1;
        end
    endtask

    initial begin
        rst_n       = 1'b0;
        req         = ZERO_N;
        passed      = 0;
        failed      = 0;
        cyc         = 0;
        model_ptr   = 0;
        exp_w       = -1;
        gcnt        = 0;
        tidx        = 0;
        exp_grant   = ZERO_N;
        armed       = 1'b0;
        done        = 1'b0;
        max_wait    = 0;
        cov_idle    = 0;
        cov_all     = 0;
        cov_rot     = 0;
        cov_held    = 0;
        cov_maxwait = 0;
        cov_rst     = 0;
        rot_mode    = 1'b0;
        held_mode   = 1'b0;
        rot_cnt     = 0;
        held_id     = 0;
        seed        = SEED;
        rnd         = 0;
        rnd2        = 0;
        v           = ZERO_N;
        r           = 1'b1;
        for (j = 0; j < N; j = j + 1) begin
            waitc[j]     = 0;
            cov_alone[j] = 0;
        end

        // Phase 1: reset with no requests.
        repeat (3) step(1'b0, ZERO_N);

        // Phase 2: no requests.
        repeat (4) step(1'b1, ZERO_N);

        // Phase 3: each requester alone, upwards then downwards.
        for (j = 0; j < N; j = j + 1) begin
            step(1'b1, ONE_N << j);
            step(1'b1, ONE_N << j);
        end
        for (j = N - 1; j >= 0; j = j - 1) begin
            step(1'b1, ONE_N << j);
        end

        // Phase 4: reset during traffic, then everyone requesting:
        // grants must rotate 0, 1, ..., N-1, 0, ... from reset.
        repeat (2) step(1'b0, ALL_N);
        rot_mode = 1'b1;
        rot_cnt  = 0;
        repeat (3 * N) step(1'b1, ALL_N);
        rot_mode = 1'b0;

        // Phase 5: longest fair wait. Grant t alone (pointer -> t+1),
        // then everyone requests: t waits exactly N-1 cycles.
        for (t = 0; t < N; t = t + 1) begin
            step(1'b1, ONE_N << t);
            repeat (N) step(1'b1, ALL_N);
        end

        // Phase 6: a held request among changing others.
        held_mode = 1'b1;
        for (h = 0; h < N; h = h + 1) begin
            held_id = h;
            repeat (6 * N) begin
                rnd = $random(seed);
                v   = rnd[N-1:0] | (ONE_N << h);
                step(1'b1, v);
            end
        end
        held_mode = 1'b0;

        // Phase 7: random traffic with occasional reset during traffic.
        repeat (500) begin
            rnd  = $random(seed);
            rnd2 = $random(seed);
            v    = rnd[N-1:0];
            r    = (rnd2[4:0] != 5'd0);
            step(r, v);
        end

        // Phase 8: drain.
        repeat (2) step(1'b1, ZERO_N);

        // Coverage: fail the run if a required case was not reached.
        chk(cov_idle > 0, 10);
        for (j = 0; j < N; j = j + 1) begin
            chk(cov_alone[j] > 0, 11);
        end
        chk((cov_all > 0) && (cov_rot >= 2 * N), 12);
        chk(cov_held > 0, 13);
        chk((cov_maxwait > 0) && (max_wait == N - 1), 14);
        chk(cov_rst > 0, 15);

        done = 1'b1;
    end

endmodule

module rr_arbiter_tb;
    reg            clk;
    reg [8*64-1:0] nonce;
    integer        passed;
    integer        failed;
    integer        have_nonce;
    integer        cycles;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    rr_arbiter_tb_harness #(.N(4), .SEED(4660))  h4 (.clk(clk));
    rr_arbiter_tb_harness #(.N(5), .SEED(23130)) h5 (.clk(clk));

    initial begin
        nonce      = {(8*64){1'b0}};
        passed     = 0;
        failed     = 0;
        cycles     = 0;
        have_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);

        while (((h4.done !== 1'b1) || (h5.done !== 1'b1)) && (cycles < 20000)) begin
            @(posedge clk);
            cycles = cycles + 1;
        end

        passed = h4.passed + h5.passed;
        failed = h4.failed + h5.failed;
        if ((h4.done !== 1'b1) || (h5.done !== 1'b1)) begin
            failed = failed + 1;
            $error("rr_arbiter_tb: timeout after %0d cycles before both harnesses finished", cycles);
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule

`default_nettype wire
=== END FILE ===
